import { MakeLogicType, afterMount, kea, key, path, props } from 'kea'
import posthog from 'posthog-js'

export type CloudAgentsSceneName = 'runs' | 'run' | 'presets' | 'preset' | 'usage' | 'settings'

export interface CloudAgentsSceneLogicProps {
    scene: CloudAgentsSceneName
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface cloudAgentsSceneLogicMeta {
    key: CloudAgentsSceneName
}

export type cloudAgentsSceneLogicType = MakeLogicType<{}, {}, CloudAgentsSceneLogicProps, cloudAgentsSceneLogicMeta>

/** Records one view for each Cloud agents scene that a person opens. */
export const cloudAgentsSceneLogic = kea<cloudAgentsSceneLogicType>([
    props({} as CloudAgentsSceneLogicProps),
    key((props) => props.scene),
    path((key) => ['products', 'cloud_agents', 'frontend', 'logics', 'cloudAgentsSceneLogic', key]),
    afterMount(({ props }) => {
        // pinned: analytics event and property names. A rename breaks the dashboards that read them.
        posthog.capture('cloud_agents_scene_viewed', { scene: props.scene })
    }),
])
